import{cancelOrderCommission,canHandleRequestNotifications,consumeStockForOrder,deletePartRequest,getCurrentUser,hasPermission,isKauaUser,markPartRequestSent,readOrderCommissions,readPartRequests,readStock,recordOrderAdvance,recordOrderCommissions,recordOrderDelivery,recordOrderReadyReceivable,savePartRequest,saveStockItems,updateOrderIdentity,updateOrderStatus,updatePartRequest}from'./supabase.js?v=20260925-2&w=5';
import{resolveOrderStockLinks}from'./order-stock-links.js';

const OWNER='cortezgaragemecanica@gmail.com',DB_KEY='cortez-garage-v1';
const owner=()=>getCurrentUser().email.toLowerCase()===OWNER;
const canReady=()=>hasPermission('readyOrders');
const esc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const money=value=>Number(value||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const normalize=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const currentOrder=()=>{const number=document.querySelector('.os-head h2')?.textContent.match(/#(.+)/)?.[1]?.trim();try{return(JSON.parse(localStorage.getItem(DB_KEY)||'{}').orders||[]).find(item=>String(item.number)===number)}catch{return null}};
const saveLocalOrder=order=>{const database=JSON.parse(localStorage.getItem(DB_KEY)||'{}'),index=(database.orders||[]).findIndex(item=>item.id===order.id);if(index>=0)database.orders[index]=order;for(const key of ['clients','vehicles']){const item=key==='clients'?order.client:order.vehicle,found=(database[key]||[]).findIndex(entry=>entry.id===item?.id);if(found>=0)database[key][found]=item}localStorage.setItem(DB_KEY,JSON.stringify(database));document.dispatchEvent(new CustomEvent('cortez:database-updated',{detail:database}))};
const closeModal=modal=>{modal?.remove();document.body.classList.remove('modal-open')};
const showModal=html=>{document.querySelector('.os-workflow-modal')?.remove();const modal=document.createElement('div');modal.className='check-popup os-workflow-modal';modal.innerHTML=`<div class="check-popup-card">${html}</div>`;document.body.append(modal);document.body.classList.add('modal-open');return modal};

function matchScore(part,item){const wanted=normalize(part.description),candidate=normalize(item.description);if(!wanted||!candidate)return 0;if(wanted===candidate)return 100;if(candidate.includes(wanted)||wanted.includes(candidate))return 80;const words=new Set(wanted.split(' ').filter(word=>word.length>2)),hits=candidate.split(' ').filter(word=>words.has(word)).length;return hits?hits/Math.max(1,words.size)*60:0}

function stockPopup(order){return new Promise(async(resolve,reject)=>{try{const parts=order.budget?.parts||[];if(!parts.some(part=>!part.refused)){resolve([]);return}const stock=await readStock(),links=resolveOrderStockLinks(parts,stock);if(!links.unresolved.length){resolve(links.selections);return}const blocks=parts.map((part,index)=>{if(part.refused||!links.unresolved.includes(index))return'';const needed=Math.max(1,Number(part.quantity||1)),matches=stock.map(item=>({item,score:matchScore(part,item)})).filter(entry=>entry.score>0).sort((a,b)=>b.score-a.score).slice(0,6),available=matches.filter(entry=>Number(entry.item.quantity||0)>=needed),hasZero=matches.some(entry=>Number(entry.item.quantity||0)<=0);return`<section class="stock-match-card" data-part="${index}"><header><div><b>${esc(part.description)}</b><small>Quantidade da O.S.: ${needed} · Valor da O.S.: ${money(part.value)}</small></div></header><label><span>Peça correspondente no estoque</span><select class="stock-choice" ${available.length?'':'disabled'}><option value="">Selecione e confirme</option>${available.map(({item})=>`<option value="${esc(item.id)}">${esc(item.description)} — saldo ${Number(item.quantity)} — ${money(Math.max(Number(item.value||0),Number(part.value||0)))}</option>`).join('')}</select></label>${matches.length?`<p class="stock-hints">Coincidências: ${matches.map(({item})=>`${esc(item.description)} (${Number(item.quantity||0)})`).join(' · ')}</p>`:'<p class="stock-hints warning">Nenhuma descrição coincidente foi encontrada.</p>'}<label class="stock-add-toggle"><input type="checkbox" class="stock-new-toggle" ${!available.length||hasZero?'checked':''}> ${hasZero?'Repor/cadastrar esta peça':'Adicionar como nova peça'}</label><div class="stock-new-fields ${!available.length||hasZero?'':'hidden'}"><div class="grid two"><label><span>Descrição</span><input class="new-description" value="${esc(part.description)}"></label><label><span>Aplicação</span><input class="new-application" placeholder="Veículo/aplicação"></label><label><span>Quantidade de entrada</span><input class="new-quantity" type="number" min="${needed}" step="1" value="${needed}"></label><label><span>Custo unitário</span><input class="new-cost" type="number" min="0" step="0.01" value="0"></label><label><span>Markup (%)</span><input class="new-markup" type="number" min="0" step="0.01" value="0"></label><label><span>Valor de venda</span><input class="new-sale" type="number" min="0" step="0.01" value="${Number(part.value||0).toFixed(2)}" readonly></label></div><small>O valor de venda nunca ficará abaixo do valor usado nesta O.S.</small></div></section>`}).join('');const modal=showModal(`<span class="eyebrow">BAIXA DE ESTOQUE</span><h3>Confirmar peças da O.S. #${esc(order.number)}</h3><p>Selecione a descrição correspondente. Se não houver saldo ou cadastro, faça a entrada da peça antes da baixa.</p><div class="stock-match-list">${blocks}</div><div class="check-popup-actions"><button type="button" class="secondary cancel-stock">Cancelar</button><button type="button" class="primary confirm-stock">Confirmar e deixar pronto</button></div>`);modal.querySelectorAll('.stock-match-card').forEach(card=>{const toggle=card.querySelector('.stock-new-toggle'),fields=card.querySelector('.stock-new-fields'),choice=card.querySelector('.stock-choice'),calculate=()=>{const index=Number(card.dataset.part),part=parts[index],cost=Number(card.querySelector('.new-cost').value||0),markup=Number(card.querySelector('.new-markup').value||0);card.querySelector('.new-sale').value=Math.max(Number(part.value||0),cost*(1+markup/100)).toFixed(2)};toggle.onchange=()=>{fields.classList.toggle('hidden',!toggle.checked);choice.disabled=toggle.checked||choice.options.length<=1};card.querySelector('.new-cost').oninput=calculate;card.querySelector('.new-markup').oninput=calculate});modal.querySelector('.cancel-stock').onclick=()=>{closeModal(modal);resolve(null)};modal.querySelector('.confirm-stock').onclick=async()=>{const button=modal.querySelector('.confirm-stock');button.disabled=true;button.textContent='Conferindo…';try{const selections=[...links.selections];for(const card of modal.querySelectorAll('.stock-match-card')){const partIndex=Number(card.dataset.part),part=parts[partIndex],needed=Math.max(1,Number(part.quantity||1)),add=card.querySelector('.stock-new-toggle').checked;if(add){const description=card.querySelector('.new-description').value.trim(),quantity=Number(card.querySelector('.new-quantity').value),value=Math.max(Number(part.value||0),Number(card.querySelector('.new-sale').value||0));if(!description||quantity<needed)throw new Error(`Informe a descrição e uma quantidade mínima de ${needed} para ${part.description}.`);const saved=await saveStockItems([{description,application:card.querySelector('.new-application').value.trim(),quantity,value}]);if(!saved[0])throw new Error(`Não foi possível cadastrar ${part.description}.`);selections.push({partIndex,stockId:saved[0].id})}else{const stockId=card.querySelector('.stock-choice').value;if(!stockId)throw new Error(`Selecione a peça correspondente a ${part.description}.`);selections.push({partIndex,stockId})}}closeModal(modal);resolve(selections)}catch(error){button.disabled=false;button.textContent='Confirmar e deixar pronto';alert(error.message)}}}catch(error){reject(error)}})}

async function makeReady(button,status){if(!canReady())return alert('Seu usuário não tem permissão para colocar a O.S. como pronta para entrega.');const order=currentOrder();if(!order)return alert('Não foi possível localizar a ordem de serviço.');if(order.status==='Entregue')return alert('Esta O.S. já foi entregue.');button.disabled=true;button.textContent='Consultando estoque…';try{const selections=await stockPopup(order);if(selections===null){button.disabled=false;button.textContent='✓ Veículo pronto para entrega';return}button.textContent='Dando baixa…';const result=await consumeStockForOrder(order,selections);if(result.missing?.length)throw new Error(`Confira o saldo destas peças: ${result.missing.join(', ')}`);order.status='Pronto para entrega';order.updatedAt=new Date().toISOString();saveLocalOrder(order);status.value=order.status;status.dispatchEvent(new Event('change',{bubbles:true}));await updateOrderStatus(order.id,order.status);await recordOrderReadyReceivable(order);button.textContent='✓ Pronto para entrega';alert('O.S. pronta para entrega. Peças baixadas e valor lançado no contas a receber.')}catch(error){button.disabled=false;button.textContent='✓ Veículo pronto para entrega';alert(error.message)}}

function editOrderPopup(order){const checks=(order.checklist||[]).map((item,index)=>`<div class="edit-check-row"><label><input type="checkbox" data-edit-check="${index}" ${item.ok?'checked':''}> ${esc(item.label)}</label><textarea data-edit-check-description="${index}" rows="2" placeholder="Descrição do checklist">${esc(item.description||'')}</textarea></div>`).join(''),modal=showModal(`<span class="eyebrow">EDITAR ORDEM DE SERVIÇO</span><h3>Cliente, veículo e checklist</h3><div class="grid two edit-identity"><label><span>Cliente</span><input id="editClientName" value="${esc(order.client?.name)}"></label><label><span>Telefone</span><input id="editClientPhone" value="${esc(order.client?.phone)}"></label><label><span>CPF</span><input id="editClientCpf" inputmode="numeric" maxlength="14" value="${esc(order.client?.cpf)}"></label><label><span>Endereço</span><input id="editClientAddress" value="${esc(order.client?.address)}"></label><label><span>Modelo</span><input id="editVehicleModel" value="${esc(order.vehicle?.model)}"></label><label><span>Placa</span><input id="editVehiclePlate" value="${esc(order.vehicle?.plate)}"></label><label><span>Ano</span><input id="editVehicleYear" value="${esc(order.vehicle?.year)}"></label><label><span>Cor</span><input id="editVehicleColor" value="${esc(order.vehicle?.color)}"></label><label><span>Quilometragem</span><input id="editVehicleKm" type="number" min="0" value="${esc(order.vehicle?.km)}"></label><label><span>Combustível</span><input id="editVehicleFuel" value="${esc(order.vehicle?.fuel)}"></label></div><h4>Checklist de entrada</h4><div class="edit-check-list">${checks}</div><div class="check-popup-actions"><button type="button" class="secondary cancel-edit-os">Cancelar</button><button type="button" class="primary save-edit-os">Salvar alterações</button></div>`);modal.querySelector('.cancel-edit-os').onclick=()=>closeModal(modal);modal.querySelector('.save-edit-os').onclick=async()=>{const button=modal.querySelector('.save-edit-os'),value=id=>modal.querySelector(id).value.trim();if(!value('#editClientName')||!value('#editVehicleModel')||!value('#editVehiclePlate'))return alert('Informe cliente, modelo e placa.');button.disabled=true;button.textContent='Salvando…';try{Object.assign(order.client,{name:value('#editClientName'),phone:value('#editClientPhone'),cpf:value('#editClientCpf'),address:value('#editClientAddress')});Object.assign(order.vehicle,{model:value('#editVehicleModel'),plate:value('#editVehiclePlate').toUpperCase(),year:value('#editVehicleYear'),color:value('#editVehicleColor'),km:value('#editVehicleKm'),fuel:value('#editVehicleFuel')});order.checklist=(order.checklist||[]).map((item,index)=>({...item,ok:modal.querySelector(`[data-edit-check="${index}"]`).checked,description:modal.querySelector(`[data-edit-check-description="${index}"]`).value.trim()}));order.updatedAt=new Date().toISOString();saveLocalOrder(order);await updateOrderIdentity(order);closeModal(modal);alert('Dados do cliente, veículo e checklist atualizados.');location.reload()}catch(error){button.disabled=false;button.textContent='Salvar alterações';alert(error.message)}}}

function advancePopup(order){const total=Number(order.total)||0,current=Number(order.advance)||0,remaining=Math.max(0,total-current),advances=Array.isArray(order.advances)&&order.advances.length?order.advances:current?[{amount:current,paymentType:order.advancePayment,createdAt:order.advanceAt}]:[],history=advances.length?`<div class="table-card finance-table advance-history"><table><thead><tr><th>Data</th><th>Caixa</th><th>Valor</th></tr></thead><tbody>${advances.map(item=>`<tr><td>${item.createdAt?new Date(item.createdAt).toLocaleString('pt-BR'):'Registro anterior'}</td><td>${esc(item.paymentType||'Não informado')}</td><td><b>${money(item.amount)}</b></td></tr>`).join('')}</tbody></table></div>`:'<p>Nenhum adiantamento registrado.</p>',modal=showModal(`<span class="eyebrow">ADIANTAMENTOS DA O.S.</span><h3>Registrar novo valor recebido</h3><p>Valor total da O.S. #${esc(order.number)}: <b>${money(total)}</b></p><div class="finance-summary"><article><span>Total já adiantado</span><b>${money(current)}</b></article><article><span>Saldo atual</span><b>${money(remaining)}</b></article></div><label><span>Novo adiantamento</span><input id="advanceAmount" type="number" min="0.01" max="${remaining}" step="0.01" placeholder="0,00"></label><label><span>Recebido em</span><select id="advancePayment"><option value="">Selecione</option>${['Dinheiro','Pix ML','Pix BB','Cartão'].map(value=>`<option>${value}</option>`).join('')}</select></label><div class="advance-preview"><span>Saldo após este adiantamento</span><b>${money(remaining)}</b></div><h4>Histórico de adiantamentos</h4>${history}<div class="check-popup-actions"><button type="button" class="secondary cancel-advance">Cancelar</button><button type="button" class="primary save-advance">Adicionar adiantamento</button></div>`),amount=modal.querySelector('#advanceAmount'),payment=modal.querySelector('#advancePayment'),preview=modal.querySelector('.advance-preview b'),refresh=()=>preview.textContent=money(Math.max(0,remaining-Number(amount.value||0)));amount.oninput=refresh;modal.querySelector('.cancel-advance').onclick=()=>closeModal(modal);modal.querySelector('.save-advance').onclick=async()=>{const button=modal.querySelector('.save-advance'),value=Number(amount.value||0);if(value<=0)return alert('Informe o valor do novo adiantamento.');if(value>remaining+.01)return alert(`O adiantamento não pode ultrapassar o saldo de ${money(remaining)}.`);if(!payment.value)return alert('Selecione onde o adiantamento foi recebido.');button.disabled=true;button.textContent='Salvando…';try{await recordOrderAdvance(order,value,payment.value);order.updatedAt=new Date().toISOString();saveLocalOrder(order);const field=document.querySelector('#orderAdvance'),outstanding=document.querySelector('#orderOutstanding');if(field)field.value=Number(order.advance||0).toFixed(2);if(outstanding)outstanding.textContent=money(Math.max(0,total-Number(order.advance||0)));closeModal(modal);alert(`Adiantamento lançado no caixa. Total adiantado: ${money(order.advance)}.`)}catch(error){button.disabled=false;button.textContent='Adicionar adiantamento';alert(error.message)}}}

const closingOutstanding=order=>document.querySelector('#orderWarranty')?.checked||order?.warranty?0:Math.max(0,Number(document.querySelector('#labor')?.value||order?.labor||0)+Number(document.querySelector('#partsValue')?.value||order?.partsValue||0)-Number(document.querySelector('#discount')?.value||order?.discount||0)-Number(order?.advance||0));
function installWarrantyFields(billing,payment,order){if(billing.querySelector('#orderWarrantyFields'))return;const paymentLabel=payment.closest('label');paymentLabel?.insertAdjacentHTML('beforebegin',`<section id="orderWarrantyFields" class="order-warranty-fields"><label class="order-warranty-toggle"><input id="orderWarranty" type="checkbox" ${order.warranty?'checked':''}><span><strong>O.S. de garantia</strong><small>Registra peças e mão de obra como custos, sem cobrar o cliente.</small></span></label><div id="orderWarrantyOptions" ${order.warranty?'':'hidden'}><div class="order-warranty-zero"><span>VALOR A RECEBER DO CLIENTE</span><strong>R$ 0,00</strong></div><label class="order-warranty-commission"><input id="warrantyPayCommissions" type="checkbox" ${order.warrantyPayCommissions?'checked':''}><span>Gerar comissão para os mecânicos nesta garantia</span></label><small>A comissão é opcional somente em O.S. de garantia.</small></div></section>`);const warranty=billing.querySelector('#orderWarranty'),options=billing.querySelector('#orderWarrantyOptions'),pay=billing.querySelector('#warrantyPayCommissions'),credit=billing.querySelector('#closingCreditFields'),outstanding=document.querySelector('#orderOutstanding'),advance=document.querySelector('#advanceOs'),commission=document.querySelector('#releaseOrderCommissions'),sync=()=>{if(warranty.checked&&Number(order.advance||0)>0){warranty.checked=false;alert('Esta O.S. possui adiantamento. Regularize o valor recebido antes de fechá-la como garantia.')}order.warranty=warranty.checked;order.warrantyPayCommissions=warranty.checked&&pay.checked;options.hidden=!warranty.checked;paymentLabel.hidden=warranty.checked;if(warranty.checked){payment.value='Garantia';if(credit)credit.hidden=true}else if(payment.value==='Garantia')payment.value='';if(outstanding)outstanding.textContent=money(closingOutstanding(order));if(advance)advance.disabled=warranty.checked||order.status==='Entregue';if(commission){commission.disabled=warranty.checked&&!pay.checked;commission.title=commission.disabled?'Marque a opção de pagar comissão nesta garantia para liberar comissões.':''}};warranty.onchange=sync;pay.onchange=sync;sync()}
function installCreditFields(billing,payment){const discount=document.querySelector('#discount'),discountLabel=discount?.closest('label')?.querySelector('span');if(discountLabel)discountLabel.textContent='Desconto no fechamento';if(!billing.querySelector('#closingCreditFields'))payment.closest('label')?.insertAdjacentHTML('afterend',`<section id="closingCreditFields" class="closing-credit-fields" hidden><h4>Pagamento a prazo</h4><label><span>Valor que ficará a prazo</span><input id="closingCreditAmount" type="number" min="0.01" step="0.01" value="0.00"></label><label><span>Data para pagamento</span><input id="closingCreditDue" type="date"></label><label id="closingImmediatePaymentLabel" hidden><span>Forma de pagamento do valor recebido agora</span><select id="closingImmediatePayment"><option value="">Selecione</option>${['Dinheiro','Cartão','Pix ML','Pix BB'].map(value=>`<option>${value}</option>`).join('')}</select></label><div class="advance-preview"><span>Valor recebido agora</span><b id="closingImmediateValue">${money(0)}</b></div><small>O valor a prazo será lançado automaticamente em Contas a Receber.</small></section>`);const fields=billing.querySelector('#closingCreditFields'),amount=billing.querySelector('#closingCreditAmount'),due=billing.querySelector('#closingCreditDue'),immediateLabel=billing.querySelector('#closingImmediatePaymentLabel'),immediate=billing.querySelector('#closingImmediatePayment'),refresh=(initializeCredit=false)=>{const order=currentOrder(),isCredit=payment.value==='Pagamento a prazo',outstanding=closingOutstanding(order);fields.hidden=!isCredit;amount.max=String(outstanding);if(initializeCredit&&isCredit&&Number(amount.value)<=0)amount.value=outstanding.toFixed(2);if(isCredit&&!due.value){const date=new Date();date.setDate(date.getDate()+30);due.value=date.toISOString().slice(0,10)}const paidNow=Math.max(0,outstanding-Number(amount.value||0));billing.querySelector('#closingImmediateValue').textContent=money(paidNow);immediateLabel.hidden=paidNow<=0;if(paidNow<=0)immediate.value=''};payment.addEventListener('change',()=>refresh(true));amount?.addEventListener('input',()=>refresh(false));discount?.addEventListener('input',()=>refresh(false));document.querySelector('#labor')?.addEventListener('input',()=>refresh(false));document.querySelector('#partsValue')?.addEventListener('input',()=>refresh(false));billing.addEventListener('cortez:order-totals-changed',()=>refresh(false));refresh(true)}
function closingTerms(order,payment){if(payment.value!=='Pagamento a prazo')return{cashPayment:payment.value,credit:null};const outstanding=closingOutstanding(order),amount=Number(document.querySelector('#closingCreditAmount')?.value||0),dueDate=document.querySelector('#closingCreditDue')?.value||'',paidNow=Math.max(0,outstanding-amount),cashPayment=document.querySelector('#closingImmediatePayment')?.value||'';if(amount<=0)return alert('Informe o valor que ficará a prazo.');if(amount>outstanding)return alert('O valor a prazo não pode ultrapassar o saldo a receber.');if(!dueDate)return alert('Informe a data para pagamento do valor a prazo.');if(paidNow>0&&!cashPayment)return alert('Selecione a forma de pagamento do valor recebido agora.');return{cashPayment,credit:{amount,dueDate}}}

const installCreditFieldsBase=installCreditFields;
installCreditFields=function(billing,payment){if(billing.dataset.creditFieldsInstalled)return;billing.dataset.creditFieldsInstalled='1';installCreditFieldsBase(billing,payment)};

let partRequests=[],partRequestsLoading=false,partRequestsLoadedAt=0;
const requestVehicle=request=>[request.vehicle?.plate,request.vehicle?.model,request.vehicle?.year,request.vehicle?.color].filter(Boolean).join(' · ');
const requestSupplierText=request=>['SOLICITAÇÃO DE ORÇAMENTO DE PEÇAS',`Veículo: ${[request.vehicle?.plate,request.vehicle?.model,request.vehicle?.year].filter(Boolean).join(' · ')||'Não informado'}`,'',...(request.items||[]).map(item=>`${Number(item.quantity||1)}x ${item.description}`)].join('\n');
async function copyText(text){try{await navigator.clipboard.writeText(text);return}catch{}const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.focus();area.select();document.execCommand('copy');area.remove()}
async function sendPartRequestToSupplier(request,button){if(!canHandleRequestNotifications())return alert('Você não tem permissão para enviar pedidos ao fornecedor.');const modal=button.closest('.os-workflow-modal'),wasSent=request.status==='Enviada',archiveOpen=modal?.querySelector('.part-request-archive')?.open;button.disabled=true;button.textContent='Preparando…';try{const text=requestSupplierText(request);await copyText(text);if(window.CortezAndroid?.shareTextToWhatsApp)window.CortezAndroid.shareTextToWhatsApp(text);else window.open(`https://wa.me/?text=${encodeURIComponent(text)}`,'_blank','noopener');await markPartRequestSent(request.id);request.status='Enviada';button.disabled=false;button.textContent='Reenviar para o fornecedor';const card=button.closest('.part-request-card'),status=card?.querySelector('.request-status');if(status){status.textContent='Enviada';status.classList.remove('pending')}await refreshPartRequestNotifications(true);if(modal?.isConnected&&modal.classList.contains('part-request-notifications-view'))showPartRequestNotifications(wasSent&&archiveOpen);else if(modal?.isConnected&&card&&!wasSent){const archive=modal.querySelector('.part-request-archive'),list=archive?.querySelector('.part-request-list');if(list){list.append(card);archive.querySelector('summary b').textContent=list.querySelectorAll('.part-request-card').length}}alert('Texto copiado. Solicitação arquivada em Já enviadas. Escolha o fornecedor no WhatsApp.')}catch(error){button.disabled=false;button.textContent=request.status==='Enviada'?'Reenviar para o fornecedor':'Mandar para o fornecedor';alert(error.message)}}
const canChangePartRequest=request=>owner()||String(request.requestedBy?.email||'').toLowerCase()===getCurrentUser().email.toLowerCase();
const canDeletePartRequest=request=>!isKauaUser()&&canChangePartRequest(request);
function partRequestCards(requests,{supplier=false}={}){return requests.map(request=>`<article class="part-request-card"><header><div><b>O.S. #${esc(request.orderNumber)}</b><small>${esc(requestVehicle(request)||'Veículo não informado')}</small></div><span class="request-status ${request.status==='Pendente'?'pending':''}">${esc(request.status||'Pendente')}</span></header><p><b>Solicitado por:</b> ${esc(request.requestedBy?.name||request.requestedBy?.email||'Usuário')}<br><small>${new Date(request.createdAt).toLocaleString('pt-BR')}</small></p><div class="part-request-items">${(request.items||[]).map(item=>`<p><strong>${Number(item.quantity||1)}x</strong><span>${esc(item.description)}${item.reason?`<small>Motivo: ${esc(item.reason)}</small>`:''}</span></p>`).join('')}</div><div class="part-request-actions">${supplier?`<button type="button" class="primary send-part-request" data-request-id="${esc(request.id)}">${request.status==='Enviada'?'Reenviar para o fornecedor':'Mandar para o fornecedor'}</button>`:''}${canChangePartRequest(request)?`<button type="button" class="secondary edit-part-request" data-request-id="${esc(request.id)}">Editar</button>`:''}${canDeletePartRequest(request)?`<button type="button" class="danger delete-part-request" data-request-id="${esc(request.id)}">Excluir</button>`:''}</div></article>`).join('')}
function reopenPartRequests(){const order=currentOrder();if(order)showPartRequestPopup(order);else showPartRequestNotifications()}
function editPartRequestPopup(request){const modal=showModal(`<span class="eyebrow">EDITAR SOLICITAÇÃO</span><h3>O.S. #${esc(request.orderNumber)}</h3><div class="part-request-editor">${(request.items||[]).map(item=>`<div class="part-request-row"><label><span>Quantidade</span><input class="request-part-quantity" type="number" min="1" step="1" value="${Number(item.quantity||1)}"></label><label><span>Descrição</span><input class="request-part-description" value="${esc(item.description)}"></label><label><span>Motivo (opcional)</span><input class="request-part-reason" value="${esc(item.reason||'')}"></label><button type="button" class="link remove-request-part">Excluir item</button></div>`).join('')}</div><button type="button" class="secondary add-request-part">+ Incluir item</button><div class="check-popup-actions"><button type="button" class="secondary cancel-edit-request">Cancelar</button><button type="button" class="primary save-edit-request">Salvar alterações</button></div>`),editor=modal.querySelector('.part-request-editor'),wire=()=>editor.querySelectorAll('.remove-request-part').forEach(button=>button.onclick=()=>{if(editor.children.length>1)button.closest('.part-request-row').remove()});wire();modal.querySelector('.add-request-part').onclick=()=>{editor.insertAdjacentHTML('beforeend',requestRow());wire()};modal.querySelector('.cancel-edit-request').onclick=()=>{closeModal(modal);reopenPartRequests()};modal.querySelector('.save-edit-request').onclick=async()=>{const button=modal.querySelector('.save-edit-request'),items=[...editor.querySelectorAll('.part-request-row')].map(row=>({quantity:Number(row.querySelector('.request-part-quantity').value||0),description:row.querySelector('.request-part-description').value.trim(),reason:row.querySelector('.request-part-reason').value.trim()}));if(items.some(item=>item.quantity<1||!item.description))return alert('Preencha quantidade e descrição de todos os itens.');button.disabled=true;button.textContent='Salvando…';try{const saved=await updatePartRequest(request.id,items),index=partRequests.findIndex(item=>item.id===request.id);if(index>=0)partRequests[index]={...request,...saved};closeModal(modal);reopenPartRequests()}catch(error){button.disabled=false;button.textContent='Salvar alterações';alert(error.message)}}}
function wirePartRequestButtons(modal){modal.querySelectorAll('.send-part-request').forEach(button=>button.onclick=()=>{const request=partRequests.find(item=>item.id===button.dataset.requestId);if(request)sendPartRequestToSupplier(request,button)});modal.querySelectorAll('.edit-part-request').forEach(button=>button.onclick=()=>{const request=partRequests.find(item=>item.id===button.dataset.requestId);if(request)editPartRequestPopup(request)});modal.querySelectorAll('.delete-part-request').forEach(button=>button.onclick=async()=>{const request=partRequests.find(item=>item.id===button.dataset.requestId);if(!request||!canDeletePartRequest(request)||!confirm('Excluir esta solicitação de peças?'))return;button.disabled=true;try{await deletePartRequest(request.id);partRequests=partRequests.filter(item=>item.id!==request.id);partRequestsLoadedAt=Date.now();closeModal(modal);renderPartRequestNotification();reopenPartRequests()}catch(error){button.disabled=false;alert(error.message)}})}
const wireSupplierButtons=wirePartRequestButtons;
function showPartRequestNotifications(archiveOpen=false){const pending=partRequests.filter(request=>request.status==='Pendente'),sentCount=partRequests.filter(request=>request.status==='Enviada').length,modal=showModal(`<span class="eyebrow">SOLICITAÇÕES DE PEÇAS</span><h3>${pending.length} solicitação(ões) pendente(s)</h3><div class="part-request-list">${pending.length?partRequestCards(pending,{supplier:true}):'<p class="empty-popup">Nenhuma solicitação pendente.</p>'}</div><details class="part-request-archive"><summary>Já enviadas <b>${sentCount}</b></summary><div class="part-request-list"></div></details><div class="check-popup-actions"><button type="button" class="secondary close-part-requests">Fechar</button></div>`),archive=modal.querySelector('.part-request-archive');modal.classList.add('part-request-notifications-view');modal.querySelector('.close-part-requests').onclick=()=>closeModal(modal);wirePartRequestButtons(modal);archive.addEventListener('toggle',()=>{if(!archive.open)return;const sent=partRequests.filter(request=>request.status==='Enviada');archive.querySelector('.part-request-list').innerHTML=sent.length?partRequestCards(sent,{supplier:true}):'<p class="empty-popup">Nenhuma solicitação já enviada.</p>';archive.querySelector('summary b').textContent=sent.length;wirePartRequestButtons(archive)});if(archiveOpen)archive.open=true}
async function openPartRequestsFromDashboard(){if(!canHandleRequestNotifications())return;try{partRequests=await readPartRequests();partRequestsLoadedAt=Date.now();renderPartRequestNotification();showPartRequestNotifications()}catch(error){alert(error.message)}}
function renderPartRequestNotification(){let button=document.querySelector('#partRequestNotifications'),panel=document.querySelector('#partRequestDashboardAlert');if(!canHandleRequestNotifications()){button?.remove();panel?.remove();return}const pending=partRequests.filter(request=>request.status==='Pendente').length,sent=partRequests.filter(request=>request.status==='Enviada').length,header=document.querySelector('.header-actions');if(!button&&header){button=document.createElement('button');button.id='partRequestNotifications';button.type='button';button.className='part-request-notification';button.onclick=openPartRequestsFromDashboard;header.prepend(button)}if(button?.isConnected){if(button.dataset.pending!==String(pending)){button.innerHTML=`<span aria-hidden="true">🔔</span><b>${pending}</b><small>Peças</small>`;button.dataset.pending=String(pending)}button.classList.toggle('has-pending',pending>0);button.setAttribute('aria-label',`${pending} solicitações de peças pendentes`)}const menu=document.querySelector('.home-menu');if(menu&&!panel){panel=document.createElement('button');panel.id='partRequestDashboardAlert';panel.type='button';panel.className='part-request-dashboard-alert';panel.onclick=openPartRequestsFromDashboard;(document.querySelector('#serviceQuoteDashboardAlert')||menu).insertAdjacentElement('afterend',panel)}const summary=`${pending}:${sent}`;if(panel?.isConnected&&panel.dataset.summary!==summary){panel.innerHTML=`<span>⚙ Solicitações de peças</span><b>${pending} pendente${pending===1?'':'s'} · ${sent} já enviada${sent===1?'':'s'} · Ver solicitações</b>`;panel.dataset.summary=summary}}
async function refreshPartRequestNotifications(force=false){if(!canHandleRequestNotifications()){renderPartRequestNotification();return}renderPartRequestNotification();if(partRequestsLoading||(!force&&Date.now()-partRequestsLoadedAt<30000))return;partRequestsLoading=true;try{const known=new Set(partRequests.map(request=>request.id)),alreadyLoaded=partRequestsLoadedAt>0,loaded=await readPartRequests(),fresh=alreadyLoaded?loaded.filter(request=>request.status==='Pendente'&&!known.has(request.id)):[];partRequests=loaded;partRequestsLoadedAt=Date.now();renderPartRequestNotification();if(fresh.length&&window.CortezAndroid?.showNotification){const request=fresh[0];window.CortezAndroid.showNotification('Nova solicitação de peças',`${request.requestedBy?.name||request.requestedBy?.email||'Mecânico'} · O.S. #${request.orderNumber}`,Date.now()%100000)}}catch(error){console.error('Falha ao carregar solicitações de peças',error)}finally{partRequestsLoading=false}}
function requestRow(){return`<div class="part-request-row"><label><span>Quantidade</span><input class="request-part-quantity" type="number" min="1" step="1" value="1"></label><label><span>Descrição</span><input class="request-part-description" autocomplete="off"></label><label><span>Motivo (opcional)</span><input class="request-part-reason" autocomplete="off"></label><button type="button" class="link remove-request-part" aria-label="Remover item">Excluir</button></div>`}
async function showPartRequestPopup(order){let requests=[];try{requests=(await readPartRequests()).filter(request=>request.orderId===order.id);partRequests=await readPartRequests();partRequestsLoadedAt=Date.now()}catch(error){return alert(error.message)}const modal=showModal(`<span class="eyebrow">SOLICITAR PEÇAS</span><h3>O.S. #${esc(order.number)} · ${esc(requestVehicle({vehicle:order.vehicle}))}</h3><div class="part-request-editor">${requestRow()}</div><button type="button" class="secondary add-request-part">+ Incluir item</button><div class="check-popup-actions"><button type="button" class="secondary cancel-part-request">Cancelar</button><button type="button" class="primary save-part-request">Salvar solicitação</button></div>${requests.length?`<h4>Solicitações desta O.S.</h4><div class="part-request-list">${partRequestCards(requests,{supplier:canHandleRequestNotifications()})}</div>`:''}`),editor=modal.querySelector('.part-request-editor');const wireRows=()=>editor.querySelectorAll('.remove-request-part').forEach(button=>button.onclick=()=>{if(editor.children.length>1)button.closest('.part-request-row').remove()});wireRows();modal.querySelector('.add-request-part').onclick=()=>{editor.insertAdjacentHTML('beforeend',requestRow());wireRows()};modal.querySelector('.cancel-part-request').onclick=()=>closeModal(modal);wireSupplierButtons(modal);modal.querySelector('.save-part-request').onclick=async()=>{const button=modal.querySelector('.save-part-request'),items=[...editor.querySelectorAll('.part-request-row')].map(row=>({quantity:Number(row.querySelector('.request-part-quantity').value||0),description:row.querySelector('.request-part-description').value.trim(),reason:row.querySelector('.request-part-reason').value.trim()}));if(items.some(item=>item.quantity<1||!item.description||!item.reason))return alert('Preencha quantidade, descrição e motivo de todos os itens.');button.disabled=true;button.textContent='Salvando…';try{const saved=await savePartRequest(order,items);partRequests.unshift(saved);partRequestsLoadedAt=Date.now();renderPartRequestNotification();if(window.CortezAndroid?.showNotification&&owner())window.CortezAndroid.showNotification('Nova solicitação de peças',`${saved.requestedBy.name} · O.S. #${saved.orderNumber}`,Date.now()%100000);closeModal(modal);alert('Solicitação salva. O proprietário receberá a notificação.')}catch(error){button.disabled=false;button.textContent='Salvar solicitação';alert(error.message)}}}
function installChecklistAndPartRequest(actions,order){const checklist=[...document.querySelectorAll('.detail')].find(section=>section.querySelector('h3')?.textContent.trim()==='Checklist de entrada');if(checklist&&!checklist.dataset.collapsible){checklist.dataset.collapsible='1';checklist.id='orderChecklistPanel';checklist.hidden=true}if(checklist&&!document.querySelector('#toggleOrderChecklist')){const button=document.createElement('button');button.id='toggleOrderChecklist';button.type='button';button.className='secondary';button.textContent='☑ Checklist';button.onclick=()=>{checklist.hidden=!checklist.hidden;button.textContent=checklist.hidden?'☑ Checklist':'Ocultar checklist';if(!checklist.hidden)checklist.scrollIntoView({behavior:'smooth',block:'start'})};actions.append(button)}if(order&&hasPermission('editOrders')&&!document.querySelector('#requestParts')){const button=document.createElement('button');button.id='requestParts';button.type='button';button.className='secondary';button.textContent='⚙ Solicitar peças';button.onclick=()=>showPartRequestPopup(order);actions.append(button)}}

const serviceCommissionRef=(order,index)=>`comissao-os-${order.id}-servico-${index+1}`;
function commissionAmount(service){const rate=Number.isFinite(Number(service?.commissionRate))?Math.min(1,Math.max(0,Number(service.commissionRate))):.5;return Number(service?.value||0)*rate}
async function commissionReleasePopup(order){
  const services=(order.budget?.services||[]).map((service,index)=>({service,index})).filter(({service})=>!service.refused),modal=showModal(`<span class="eyebrow">COMISSÕES ANTECIPADAS</span><h3>O.S. #${esc(order.number)} · liberar por serviço</h3><p>Carregando liberações…</p><div class="check-popup-actions"><button type="button" class="secondary close-commission-release">Fechar</button></div>`);
  modal.classList.add('commission-release-popup');modal.querySelector('.close-commission-release').onclick=()=>closeModal(modal);
  const refresh=async()=>{try{
    const records=await readOrderCommissions(order.id),byReference=new Map(records.map(record=>[record.reference,record])),legacy=records.filter(record=>!record.reference.includes('-servico-')),legacyBlocks=legacy.map(record=>`<article class="commission-legacy-row"><div><b>Liberação agrupada anterior</b><small>${esc(record.mechanic)} · ${money(record.amount)} · ${record.status==='Realizado'?'Paga':'Liberada'}</small></div>${record.status==='Realizado'?'<button type="button" class="secondary" disabled>✓ Paga</button>':`<button type="button" class="danger cancel-commission-release" data-id="${esc(record.id)}">Cancelar liberação</button>`}</article>`).join(''),lockedByLegacy=legacy.length>0;
    const rows=services.map(({service,index})=>{const record=byReference.get(serviceCommissionRef(order,index)),amount=commissionAmount(service),valid=Boolean((service.mechanic||order.mechanic)&&amount>0),status=record?.status==='Realizado'?'Paga':record?'Liberada':'Não liberada',action=record?.status==='Realizado'?'<button type="button" class="secondary" disabled>✓ Paga</button>':record?`<button type="button" class="danger cancel-commission-release" data-id="${esc(record.id)}">Cancelar liberação</button>`:`<button type="button" class="primary release-one-commission" data-index="${index}" ${!valid||lockedByLegacy?'disabled':''}>Liberar comissão</button>`;return`<article class="commission-service-row"><div class="commission-service-name" data-label="Serviço"><b>${esc(service.description||`Serviço ${index+1}`)}</b></div><div data-label="Mecânico">${esc(service.mechanic||order.mechanic||'Sem mecânico')}</div><div data-label="Valor do serviço">${money(service.value)}</div><div data-label="Comissão"><strong>${money(amount)}</strong></div><div data-label="Status"><span class="commission-release-status ${record?.status==='Realizado'?'paid':record?'released':'pending'}">${status}</span></div><div class="commission-service-action" data-label="Ação">${action}</div></article>`}).join(''),available=services.filter(({service,index})=>!byReference.has(serviceCommissionRef(order,index))&&(service.mechanic||order.mechanic)&&commissionAmount(service)>0).map(({index})=>index);
    modal.querySelector('.check-popup-card').innerHTML=`<header class="commission-release-window-head"><div><span class="eyebrow">COMISSÕES ANTECIPADAS</span><h3>O.S. #${esc(order.number)} · liberar por serviço</h3><p>Libere somente os serviços desejados. Uma liberação pendente pode ser cancelada; uma comissão já paga permanece bloqueada.</p></div><strong>${services.length} serviço${services.length===1?'':'s'}</strong></header>${legacy.length?`<div class="access-restricted-note">Esta O.S. possui uma liberação agrupada da versão anterior. Cancele-a para usar a liberação por serviço.</div><div class="commission-legacy-list">${legacyBlocks}</div>`:''}<div class="commission-release-list"><div class="commission-release-columns"><span>Serviço</span><span>Mecânico</span><span>Valor do serviço</span><span>Comissão</span><span>Status</span><span>Ação</span></div>${rows||'<p class="commission-release-empty">Nenhum serviço disponível para comissão.</p>'}</div><div class="check-popup-actions"><button type="button" class="secondary close-commission-release">Fechar</button>${available.length&&!lockedByLegacy?`<button type="button" class="primary release-all-commissions">Liberar todas (${available.length})</button>`:''}</div>`;
    modal.querySelector('.close-commission-release').onclick=()=>closeModal(modal);
    modal.querySelectorAll('.release-one-commission').forEach(button=>button.onclick=async()=>{button.disabled=true;button.textContent='Liberando…';try{await recordOrderCommissions(order,[Number(button.dataset.index)]);await refresh()}catch(error){button.disabled=false;button.textContent='Liberar comissão';alert(error.message)}});
    modal.querySelector('.release-all-commissions')?.addEventListener('click',async event=>{const button=event.currentTarget;button.disabled=true;button.textContent='Liberando…';try{await recordOrderCommissions(order,available);await refresh()}catch(error){button.disabled=false;button.textContent=`Liberar todas (${available.length})`;alert(error.message)}});
    modal.querySelectorAll('.cancel-commission-release').forEach(button=>button.onclick=async()=>{if(!confirm('Cancelar esta liberação antecipada de comissão?'))return;button.disabled=true;button.textContent='Cancelando…';try{await cancelOrderCommission(button.dataset.id);await refresh()}catch(error){button.disabled=false;button.textContent='Cancelar liberação';alert(error.message)}})
  }catch(error){modal.querySelector('.check-popup-card').innerHTML=`<span class="eyebrow">COMISSÕES ANTECIPADAS</span><h3>Não foi possível carregar</h3><p>${esc(error.message)}</p><div class="check-popup-actions"><button type="button" class="secondary close-commission-release">Fechar</button></div>`;modal.querySelector('.close-commission-release').onclick=()=>closeModal(modal)}};
  await refresh()
}

function installWorkflow(){
  const actions=document.querySelector('.os-head>div:last-child'),status=document.querySelector('#status');if(!actions||!status)return;
  const order=currentOrder(),billing=document.querySelector('.billing'),approval=document.querySelector('.budget-approval');
  if(!canReady()){const readyOption=status.querySelector('option[value="Pronto para entrega"]');if(readyOption)readyOption.disabled=true}
  if(order&&billing&&!document.querySelector('#orderAdvance')){const total=billing.querySelector('.total');total?.insertAdjacentHTML('beforebegin',`<label class="order-advance-field"><span>Adiantamento</span><input id="orderAdvance" type="number" value="${Number(order.advance||0).toFixed(2)}" readonly></label><div class="order-outstanding"><span>SALDO A RECEBER</span><strong id="orderOutstanding">${money(order.warranty?0:Math.max(0,Number(order.total||0)-Number(order.advance||0)))}</strong></div>`)}
  if(!document.querySelector('#editOsIdentity')){const edit=document.createElement('button');edit.id='editOsIdentity';edit.type='button';edit.className='secondary';edit.textContent='✎ Editar';edit.onclick=()=>{const order=currentOrder();if(order)editOrderPopup(order)};actions.append(edit)}
  if(canReady()&&!document.querySelector('#readyOs')){const ready=document.createElement('button');ready.id='readyOs';ready.type='button';ready.className='primary wide';ready.textContent=status.value==='Pronto para entrega'?'✓ Pronto para entrega':'✓ Veículo pronto para entrega';ready.disabled=['Pronto para entrega','Entregue'].includes(status.value);ready.onclick=()=>makeReady(ready,status);(approval||actions).insertBefore(ready,approval?.querySelector('#previousStatus')||null)}
  const ready=document.querySelector('#readyOs');if(canReady()&&ready&&approval&&ready.parentElement!==approval)approval.insertBefore(ready,approval.querySelector('#previousStatus'));if(!canReady())ready?.remove();
  if(owner()&&!document.querySelector('#advanceOs')){const advance=document.createElement('button');advance.id='advanceOs';advance.type='button';advance.className='secondary';advance.textContent='R$ Adiantamento';advance.disabled=status.value==='Entregue'||Boolean(order?.warranty);advance.onclick=()=>{const order=currentOrder();if(order)advancePopup(order)};actions.append(advance)}
  if(owner()&&order&&status.value!=='Entregue'&&!document.querySelector('#releaseOrderCommissions')){const commission=document.createElement('button');commission.id='releaseOrderCommissions';commission.type='button';commission.className='secondary';commission.textContent='R$ Comissões antecipadas';commission.disabled=Boolean(order.warranty&&!order.warrantyPayCommissions);commission.onclick=()=>commissionReleasePopup(order);actions.append(commission)}
  if(!owner()){document.querySelector('#openClosing')?.remove();return}
  const save=document.querySelector('#saveOs');if(!billing||!save)return;billing.classList.add('owner-closing-panel');
  if(!document.querySelector('#openClosing')){const open=document.createElement('button');open.id='openClosing';open.type='button';open.className='secondary';open.textContent='Fechamento';open.onclick=()=>{billing.classList.add('closing-open');billing.scrollIntoView({behavior:'smooth',block:'start'})};actions.append(open)}
  const payment=document.querySelector('#payment'),paymentLabel=payment?.closest('label')?.querySelector('span');if(paymentLabel&&paymentLabel.textContent!=='Condição / forma de pagamento')paymentLabel.textContent='Condição / forma de pagamento';for(const value of ['Pix ML','Pix BB','Pagamento a prazo','Garantia'])if(payment&&![...payment.options].some(option=>option.value===value))payment.add(new Option(value,value));
  installCreditFields(billing,payment);installWarrantyFields(billing,payment,order);
  if(save.dataset.closingInstalled)return;save.dataset.closingInstalled='1';save.textContent='Fechar O.S.';const originalSave=save.onclick;
  save.onclick=async event=>{event.preventDefault();const current=currentOrder(),warranty=Boolean(document.querySelector('#orderWarranty')?.checked),payCommissions=warranty&&Boolean(document.querySelector('#warrantyPayCommissions')?.checked);if(!warranty&&!payment?.value)return alert('Selecione a condição / forma de pagamento antes de fechar a O.S.');if(warranty&&Number(current?.advance||0)>0)return alert('Regularize o adiantamento antes de fechar esta O.S. como garantia.');const terms=warranty?{cashPayment:'',credit:null}:closingTerms(current,payment);if(!terms)return;if(warranty&&!payCommissions){try{const commissions=await readOrderCommissions(current.id);if(commissions.some(item=>item.status==='Realizado'))return alert('Esta O.S. já possui comissão paga. Marque a opção de gerar comissão para concluir a garantia.')}catch(error){return alert(error.message)}}const confirmation=warranty?`Fechar esta O.S. como Garantia, sem valor a receber, ${payCommissions?'gerando':'sem gerar'} comissões?`:'Fechar esta O.S. como Entregue e gerar as comissões?';if(!confirm(confirmation))return;const previous=status.value;save.disabled=true;save.textContent='Fechando…';status.value='Entregue';try{if(current){current.warranty=warranty;current.warrantyPayCommissions=payCommissions;current.payment=warranty?'Garantia':payment.value;saveLocalOrder(current)}await originalSave?.call(save,event);const order=currentOrder();if(!order)throw new Error('Não foi possível localizar a ordem de serviço.');order.status='Entregue';order.warranty=warranty;order.warrantyPayCommissions=payCommissions;order.payment=warranty?'Garantia':payment.value;order.closingCreditAmount=Number(terms.credit?.amount||0);order.closingCreditDueDate=terms.credit?.dueDate||'';saveLocalOrder(order);await updateOrderStatus(order.id,'Entregue');await recordOrderDelivery(order,terms.cashPayment,terms.credit);saveLocalOrder(order);document.dispatchEvent(new CustomEvent('cortez:order-delivered',{detail:{order}}));save.disabled=true;save.textContent=warranty?'✓ Garantia fechada':'✓ O.S. entregue';alert(warranty?`O.S. de garantia fechada sem cobrança. ${payCommissions?'As comissões foram geradas.':'Nenhuma comissão foi gerada.'}`:terms.credit?'O.S. entregue. Valor a prazo lançado em Contas a Receber e comissões geradas.':'O.S. entregue. Recebimento lançado no caixa e comissões geradas.')}catch(error){status.value=previous;save.disabled=false;save.textContent='Fechar O.S.';alert(error.message)}}
}

document.addEventListener('change',event=>{if(event.target?.id!=='status'||event.target.value!=='Pronto para entrega'||canReady())return;event.preventDefault();event.stopImmediatePropagation();event.target.value=currentOrder()?.status||'Em andamento';alert('Seu usuário não tem permissão para colocar a O.S. como pronta para entrega.')},true);
document.addEventListener('input',event=>{if(!event.target.matches?.('#labor,#partsValue,#discount'))return;setTimeout(()=>{const outstanding=document.querySelector('#orderOutstanding'),advance=document.querySelector('#orderAdvance');if(!outstanding||!advance)return;const total=Number(document.querySelector('#labor')?.value||0)+Number(document.querySelector('#partsValue')?.value||0)-Number(document.querySelector('#discount')?.value||0);outstanding.textContent=money(document.querySelector('#orderWarranty')?.checked?0:Math.max(0,total-Number(advance.value||0)))},0)});
window.__cortezGuidedStock=true;
const showPartRequestPopupBase=showPartRequestPopup;
function archiveSentPartRequestsInOrder(){const modal=document.querySelector('.os-workflow-modal'),list=modal?.querySelector('.part-request-list');if(!modal?.querySelector('.save-part-request')||!list||modal.querySelector('.part-request-archive'))return;const sentCards=[...list.querySelectorAll('.part-request-card')].filter(card=>card.querySelector('.request-status')?.textContent.trim()==='Enviada'),archive=document.createElement('details');archive.className='part-request-archive';archive.innerHTML=`<summary>Já enviadas <b>${sentCards.length}</b></summary><div class="part-request-list"></div>`;list.insertAdjacentElement('afterend',archive);archive.querySelector('.part-request-list').append(...sentCards)}
showPartRequestPopup=async order=>{await showPartRequestPopupBase(order);installOptionalPartReason();archiveSentPartRequestsInOrder()};
function installOptionalPartReason(){const modal=document.querySelector('.os-workflow-modal'),button=modal?.querySelector('.save-part-request'),editor=modal?.querySelector('.part-request-editor');if(!button||!editor||button.dataset.optionalReason)return;button.dataset.optionalReason='1';button.onclick=async()=>{const order=currentOrder(),items=[...editor.querySelectorAll('.part-request-row')].map(row=>({quantity:Number(row.querySelector('.request-part-quantity').value||0),description:row.querySelector('.request-part-description').value.trim(),reason:row.querySelector('.request-part-reason').value.trim()}));if(!order)return alert('Não foi possível localizar a ordem de serviço.');if(items.some(item=>item.quantity<1||!item.description))return alert('Preencha quantidade e descrição de todos os itens.');button.disabled=true;button.textContent='Salvando…';try{const saved=await savePartRequest(order,items);partRequests.unshift(saved);partRequestsLoadedAt=Date.now();renderPartRequestNotification();closeModal(modal);alert('Solicitação salva. O proprietário receberá a notificação.')}catch(error){button.disabled=false;button.textContent='Salvar solicitação';alert(error.message)}}}
function installObservationLabel(){const field=document.querySelector('#services'),label=field?.closest('label')?.querySelector('span'),placeholder='Digite uma observação sobre o serviço';if(label&&label.textContent!=='Observação')label.textContent='Observação';if(field&&field.placeholder!==placeholder)field.placeholder=placeholder}
function installPartFeatures(){refreshPartRequestNotifications();const actions=document.querySelector('.os-head>div:last-child'),order=currentOrder();if(actions&&order)installChecklistAndPartRequest(actions,order);installOptionalPartReason();installObservationLabel()}
new MutationObserver(()=>{installWorkflow();installPartFeatures()}).observe(document.querySelector('#app'),{childList:true,subtree:true});
installWorkflow();
installPartFeatures();
setInterval(()=>refreshPartRequestNotifications(true),60000);
